<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\BookingController;
use App\Http\Controllers\ServiceController;
use App\Http\Controllers\Admin\AuthController as AdminAuthController;
use App\Http\Controllers\Admin\DashboardController;
use App\Http\Controllers\Admin\ServiceAdminController;
use App\Http\Controllers\Admin\BookingAdminController;
use App\Http\Controllers\Admin\HoursAdminController;
use App\Http\Controllers\Admin\GalleryAdminController;
use App\Http\Controllers\Admin\TestimonialAdminController; use App\Http\Controllers\Admin\CategoryAdminController; use App\Http\Controllers\Admin\TranslationController; use App\Http\Controllers\Admin\MailSettingsAdminController; use App\Http\Controllers\TestimonialController; use App\Models\AdminNotification;
use App\Models\GalleryItem; use App\Models\Testimonial; use App\Models\Service;
Route::get('/', fn()=>view('welcome',['services'=>Service::where('is_active',true)->orderBy('sort_order')->limit(5)->get(),'galleryItems'=>GalleryItem::where('is_published',true)->orderBy('sort_order')->limit(8)->get(),'testimonials'=>Testimonial::where('is_published',true)->latest()->limit(6)->get()]))->name('home');
Route::view('/a-propos','about')->name('about'); Route::view('/contact','contact')->name('contact'); Route::post('/temoignages',[TestimonialController::class,'store'])->middleware('throttle:5,10')->name('testimonials.store');
Route::get('/prestations',[ServiceController::class,'index'])->name('prestations');
Route::get('/reservation',[BookingController::class,'create'])->name('booking.create'); Route::get('/reservation/creneaux',[BookingController::class,'slots'])->name('booking.slots'); Route::get('/reservation/disponibilites-mois',[BookingController::class,'monthAvailability'])->name('booking.month-slots'); Route::post('/reservation',[BookingController::class,'store'])->middleware('throttle:10,1')->name('booking.store'); Route::get('/reservation/confirmation/{booking:reference}',[BookingController::class,'confirmation'])->name('booking.confirmation');
Route::prefix('administration')->name('admin.')->group(function(){Route::get('/connexion',[AdminAuthController::class,'show'])->name('login');Route::post('/connexion',[AdminAuthController::class,'login'])->middleware('throttle:5,1')->name('login.submit');Route::post('/deconnexion',[AdminAuthController::class,'logout'])->name('logout');Route::middleware(['auth','admin'])->group(function(){Route::get('/',DashboardController::class)->name('dashboard');Route::get('/prestations',[ServiceAdminController::class,'index'])->name('services.index');Route::post('/prestations',[ServiceAdminController::class,'store'])->name('services.store');Route::put('/prestations/{service}',[ServiceAdminController::class,'update'])->name('services.update');Route::delete('/prestations/{service}',[ServiceAdminController::class,'destroy'])->name('services.destroy');Route::get('/rendez-vous',[BookingAdminController::class,'index'])->name('bookings.index');Route::get('/agenda/controle-date',[BookingAdminController::class,'dateConflicts'])->name('agenda.date-conflicts');Route::get('/notifications/non-lues',fn()=>response()->json(['count'=>AdminNotification::whereNull('read_at')->count()]))->name('notifications.unread-count');Route::post('/notifications/{notification}/lue',[BookingAdminController::class,'markNotificationRead'])->name('notifications.read');Route::put('/rendez-vous/{booking}',[BookingAdminController::class,'update'])->name('bookings.update');Route::get('/horaires',[HoursAdminController::class,'index'])->name('hours.index');Route::get('/agenda/evenements',[HoursAdminController::class,'events'])->name('agenda.events');Route::get('/agenda/jour',[HoursAdminController::class,'day'])->name('agenda.day');Route::post('/agenda/jour',[HoursAdminController::class,'saveDay'])->name('agenda.day.save');Route::get('/categories',[CategoryAdminController::class,'index'])->name('categories.index');Route::post('/categories/prestations',[CategoryAdminController::class,'storeService'])->name('categories.services.store');Route::put('/categories/prestations/{category}',[CategoryAdminController::class,'updateService'])->name('categories.services.update');Route::delete('/categories/prestations/{category}',[CategoryAdminController::class,'deleteService'])->name('categories.services.delete');Route::post('/categories/galerie',[CategoryAdminController::class,'storeGallery'])->name('categories.gallery.store');Route::put('/categories/galerie/{category}',[CategoryAdminController::class,'updateGallery'])->name('categories.gallery.update');Route::delete('/categories/galerie/{category}',[CategoryAdminController::class,'deleteGallery'])->name('categories.gallery.delete');Route::post('/traduction',[TranslationController::class,'translate'])->middleware('throttle:20,1')->name('translation.translate');Route::get('/parametres/e-mails',[MailSettingsAdminController::class,'index'])->name('mail-settings.index');Route::post('/parametres/e-mails',[MailSettingsAdminController::class,'save'])->name('mail-settings.save');Route::post('/parametres/e-mails/test',[MailSettingsAdminController::class,'test'])->middleware('throttle:5,1')->name('mail-settings.test');Route::post('/horaires',[HoursAdminController::class,'save'])->name('hours.save');Route::post('/conges',[BookingAdminController::class,'addClosure'])->name('closures.store');Route::delete('/conges/{closure}',[HoursAdminController::class,'deleteClosure'])->name('closures.destroy');Route::get('/galerie',[GalleryAdminController::class,'index'])->name('gallery.index');Route::post('/galerie',[GalleryAdminController::class,'store'])->name('gallery.store');Route::patch('/galerie/{item}/visibilite',[GalleryAdminController::class,'toggle'])->name('gallery.toggle');Route::delete('/galerie/{item}',[GalleryAdminController::class,'destroy'])->name('gallery.destroy');Route::get('/temoignages',[TestimonialAdminController::class,'index'])->name('testimonials.index');Route::post('/temoignages',[TestimonialAdminController::class,'store'])->name('testimonials.store');Route::put('/temoignages/{item}',[TestimonialAdminController::class,'update'])->name('testimonials.update');Route::patch('/temoignages/{item}/visibilite',[TestimonialAdminController::class,'toggle'])->name('testimonials.toggle');Route::delete('/temoignages/{item}',[TestimonialAdminController::class,'destroy'])->name('testimonials.destroy');});});
